    RSA* rsa = RSA_new();
    if (!rsa) {
        std::cerr << "Failed to create RSA key." << std::endl;
        return "";
    }

    BIGNUM* bn = BN_new();
    if (!bn || !BN_set_word(bn, 2048)) {
        std::cerr << "Failed to set key size." << std::endl;
        RSA_free(rsa);
        return "";
    }

    if (!RSA_generate_key_ex(rsa, BN_get_word(bn), 65537, nullptr)) {
        std::cerr << "Failed to generate RSA key." << std::endl;
        RSA_free(rsa);
        return "";
    }

    BIO* bio = BIO_new(BIO_s_mem());
    if (!bio || !PEM_write_bio_RSAPrivateKey(bio, rsa, nullptr, nullptr, 0, nullptr, nullptr)) {
        std::cerr << "Failed to write PEM data." << std::endl;
        RSA_free(rsa);
        return "";
    }

    char* pem_data = nullptr;
    long pem_len = BIO_get_mem_data(bio, &pem_data);
    std::string result(pem_data, pem_len);

    BIO_free(bio);
    RSA_free(rsa);
    BN_free(bn);

    return result;
}
